begin;
-- Reciprocal guard: payroll cannot accrue a month already posted through
-- Transport Driver Khata. This prevents the same employee/month expense twice.
create or replace function public.accrue_employee_salary(p_employee_id uuid,p_salary_month date) returns jsonb language plpgsql security definer set search_path='public','pg_temp' as $$
declare v_company uuid:=public.current_company_id();v_bu uuid:=public.current_business_unit_id();v_user uuid:=public.legacy_data_user_id();v_month date:=date_trunc('month',p_salary_month)::date;v_name text;v_salary numeric;v_effective date;v_expense uuid;v_payable uuid;v_je uuid:=gen_random_uuid();v_no text;v_expense_name text;v_payable_name text;v_existing record;v_legacy_expensed numeric:=0;v_gl_accrual numeric:=0;
begin
 perform public.assert_module_permission('accounting','post');
 if exists(select 1 from public.transport_driver_month_closings c where c.company_id=v_company and c.business_unit_id=v_bu and c.employee_id=p_employee_id and c.month=v_month) then raise exception 'Transport Driver Khata is already posted for this employee/month. Reverse/correct it before payroll accrual.';end if;
 select a.*,e.name into v_existing from public.employee_salary_accruals a join public.employees e on e.id=a.employee_id where a.company_id=v_company and a.business_unit_id=v_bu and a.employee_id=p_employee_id and a.salary_month=v_month;if found then return jsonb_build_object('success',true,'already_accrued',true,'entry_no',v_existing.voucher_no,'monthly_salary',v_existing.monthly_salary);end if;
 select e.name into v_name from public.employees e where e.id=p_employee_id and e.company_id=v_company and e.is_active=true;if not found then raise exception 'Active employee not found.';end if;
 select monthly_salary,effective_from into v_salary,v_effective from public.employee_salary_profiles where company_id=v_company and employee_id=p_employee_id;if not found then raise exception 'Monthly salary is not configured.';end if;if v_month<date_trunc('month',v_effective)::date then raise exception 'Salary month is before salary effective date.';end if;
 select account_id into v_expense from public.account_mappings where company_id=v_company and mapping_key='salary_expense';select id into v_payable from public.chart_of_accounts where company_id=v_company and detail_type='Salary Payable' and is_active=true and is_group=false order by created_at limit 1;if v_expense is null or v_payable is null then raise exception 'Salary Expense / Salary Payable setup is missing.';end if;
 select name into v_expense_name from public.chart_of_accounts where id=v_expense and company_id=v_company;select name into v_payable_name from public.chart_of_accounts where id=v_payable and company_id=v_company;
 select coalesce(sum(p.amount),0) into v_legacy_expensed from public.employee_salary_payments p where p.company_id=v_company and p.business_unit_id=v_bu and p.employee_id=p_employee_id and p.salary_month=v_month and exists(select 1 from public.journal_lines jl where jl.entry_id=p.journal_entry_id and jl.account_id=v_expense and jl.debit>0);
 v_gl_accrual:=greatest(round(v_salary-v_legacy_expensed,2),0);v_no:='SAL-ACC-'||upper(substr(replace(v_je::text,'-',''),1,10));
 if v_gl_accrual>0 then insert into public.journal_entries(id,user_id,company_id,business_unit_id,entry_no,entry_date,description,status,payment_mode,party_name,trans_type,created_by,source_module,source_document_type) values(v_je,v_user,v_company,v_bu,v_no,v_month,'Salary accrual - '||v_name||' - '||to_char(v_month,'Mon YYYY'),'draft','Accrual',v_name,'Salary Accrual',auth.uid(),'payroll','salary_accrual');insert into public.journal_lines(user_id,company_id,business_unit_id,entry_id,account,account_id,debit,credit,party_name,base_debit,base_credit) values(v_user,v_company,v_bu,v_je,v_expense_name,v_expense,v_gl_accrual,0,v_name,v_gl_accrual,0),(v_user,v_company,v_bu,v_je,v_payable_name,v_payable,0,v_gl_accrual,v_name,0,v_gl_accrual);perform public.post_journal_entry(v_je);else v_je:=(select journal_entry_id from public.employee_salary_payments where company_id=v_company and business_unit_id=v_bu and employee_id=p_employee_id and salary_month=v_month order by payment_date limit 1);v_no:='LEGACY-'||to_char(v_month,'YYYYMM');end if;
 insert into public.employee_salary_accruals(user_id,company_id,business_unit_id,employee_id,salary_month,monthly_salary,journal_entry_id,voucher_no) values(v_user,v_company,v_bu,p_employee_id,v_month,round(v_salary,2),v_je,v_no);
 return jsonb_build_object('success',true,'already_accrued',false,'entry_no',v_no,'monthly_salary',round(v_salary,2),'gl_accrual',v_gl_accrual,'legacy_expensed',v_legacy_expensed);
end $$;
grant execute on function public.accrue_employee_salary(uuid,date) to authenticated;
commit;
